// th16_s5_w08 — TH16 v1.00a Stage 5 道中 第 8 波
// 源入口：st05.ecl.txt:1294-1312 MainSub07（8 组环形编队）
// 依赖：MainSub07b 1314-1334、ECir03 449-484、ECir03_at 541-598。
// 死亡回调 ECir03DeadAttack1/Et1（486-539）在无敌外壳下不可达，见 report.md。

const TIME_LIMIT: int = 2260;
const OPENING_BUFFER: int = 120;

// 源 etSprite(0,4,6)：TH16 type 4 / color 6；复用已核同值 TH18 槽。
const TH16_BALL: int = 416;

// 源 enmCreate(..., 150, 1000, 1) 的血量；掉落/分数按训练口径省略。
const ECIR_HP: int = 150;
// 源 setHitbox(16,16)/setHurtbox(24,24)，普通圆形取第一值×0.5。
const ECIR_HITBOX: fx = 8fx;
const ECIR_HURTBOX: fx = 12fx;

// 源 movePosRel(%RANDF2*16, %RANDF2*16)：两次独立抽样，先 x 后 y。
sub spawn_at(x0: fx, y0: fx) {
    var ux: fx = (rand(65536) - 32768) as fx / 32768;
    var uy: fx = (rand(65536) - 32768) as fx / 32768;
    _ = spawn_enemy(x0 + 16fx * ux, y0 + 16fx * uy, ECIR_HP, 0, 0, 0,
                    ecir03(x0, y0));
}

// 源 circlePos(C,D,angle,64) + enmCreate：五次环上创建（间隔10帧），最后中心。
sub group(ax: fx, ay: fx) {
    spawn_at(ax + 64fx * cos(270deg), ay + 64fx * sin(270deg));
    wait(10);
    spawn_at(ax + 64fx * cos(54deg), ay + 64fx * sin(54deg));
    wait(10);
    spawn_at(ax + 64fx * cos(198deg), ay + 64fx * sin(198deg));
    wait(10);
    spawn_at(ax + 64fx * cos(342deg), ay + 64fx * sin(342deg));
    wait(10);
    spawn_at(ax + 64fx * cos(126deg), ay + 64fx * sin(126deg));
    wait(10);
    spawn_at(ax, ay);
}

// 源 ECir03_at 的 etAim(0,1) 固定方向扇形，层数恒1。
// 每弹 ANIM a=1 的出生退位移 = position -= 4*velocity，折算为沿弹角后退 4*speed。
sub fire_fan(n: int, speed: fx, base: angle) {
    var back: fx = 4fx * speed;
    for i in 0..n {
        var off: int = 0;
        if n == 2 {
            off = 1820;
            if i == 1 { off = -1820; }
        }
        if n == 3 {
            if i == 1 { off = -3641; }
            if i == 2 { off = 3641; }
        }
        var a: angle = base + (off as angle);
        var bx: fx = $self_x - back * cos(a);
        var by: fx = $self_y - back * sin(a);
        _ = fire(TH16_BALL, 6, bx, by, speed, a, none, none);
    }
}

// 源 ECir03_at：E=3波/1颗/1.5速；N=10波/1颗/3.0；H=10波/2颗/3.0；L=10波/3颗/3.0。
// 每波角度 = ANGLE_PLAYER + RANDF2*0.34906584(H/L；E/N仍抽一次乘0)，扇形间距20°。
async sub ecir03_shoot() {
    var rank: int = global(GVAR_RANK);
    var waves: int = 10;
    var count: int = 1;
    var speed: fx = 3fx;
    var spread: fx = 0fx;
    if rank == 0 { waves = 3; speed = 1.5fx; }
    if rank == 2 { count = 2; spread = 3641fx; }
    if rank == 3 { count = 3; spread = 3641fx; }
    wait(10);
    for w in 0..waves {
        var u: fx = (rand(65536) - 32768) as fx / 32768;
        var extra: int = (u * spread) as int;
        var base: angle = aim_player() + (extra as angle);
        fire_fan(count, speed, base);
        wait(120);
    }
}

// 源 ECir03：出生 REL 抖动由 spawn_at 预置，60帧二次加速归零；
// 60帧后异步射击；再60帧后朝(0,360)以0速定向并120帧匀速加速到1px/帧。
async sub ecir03(x0: fx, y0: fx) {
    set_invuln(65535);
    set_hitbox(ECIR_HITBOX);
    set_hurtbox(ECIR_HURTBOX);
    move_to(60, x0, y0, EASE_QUAD_IN);
    wait(60);
    spawn ecir03_shoot();
    wait(60);
    var dir: angle = atan2(360fx - $self_y, 0fx - $self_x);
    move_vel(0, dir, 0fx, EASE_LINEAR);
    move_speed(120, 1fx, EASE_LINEAR);
    loop { wait(1); }
}

// 源 MainSub07：八组环形编队，组内50帧、组间120帧，第七组后间隔100帧。
async sub pattern() {
    wait(OPENING_BUFFER);
    group(0fx, 128fx);
    wait(120);
    group(-64fx, 128fx);
    wait(120);
    group(96fx, 128fx);
    wait(120);
    group(-128fx, 128fx);
    wait(120);
    group(128fx, 128fx);
    wait(120);
    group(0fx, 128fx);
    wait(120);
    group(-64fx, 128fx);
    wait(100);
    group(96fx, 128fx);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
